targets.query:
from(bucket: "plc_data_bucket")
  |> range(start: -5m)
  |> filter(fn: (r) =>
    r._measurement == "AI_PV_DATA" and
    r._field == "ai_00pv"
  )
  |> aggregateWindow(every: v.windowPeriod, fn: mean, createEmpty: false)
  |> map(fn: (r) => ({
        r with
        _time: r._time,
        _value: float(v: r._value)
      })
    )

